#!/usr/bin/env python3
"""Overdue fee statements: python3 fees.py INPUT_DIR OUTPUT_FILE (see /app/docs)."""
import csv
import json
import os
import re
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]


# ---------------------------------------------------------------- helpers
def read_text(path):
    with open(path, "r", encoding="utf-8-sig", newline="") as f:
        return f.read()


def read_csv(path):
    text = read_text(path)
    rows = []
    reader = csv.reader(text.splitlines())
    header = None
    for row in reader:
        if header is None:
            header = [h.strip().lstrip("\ufeff") for h in row]
            continue
        if not row or all(not c.strip() for c in row):
            continue
        d = {}
        for i, h in enumerate(header):
            d[h] = row[i] if i < len(row) else ""
        rows.append(d)
    return rows


def cents(text):
    return int((Decimal(text.strip()) * 100).to_integral_value(rounding=ROUND_HALF_UP))


def parse_date(s):
    return date.fromisoformat(s.strip())


def patron_key(s):
    digits = re.sub(r"\D", "", s or "")
    return int(digits) if digits else None


def parse_offset(s):
    s = s.strip()
    m = re.fullmatch(r"([+-])(\d{1,2}):?(\d{2})?", s)
    sign = -1 if m.group(1) == "-" else 1
    return sign * (int(m.group(2)) * 60 + int(m.group(3) or 0))


def parse_ini(path):
    sections = {}
    cur = None
    for line in read_text(path).splitlines():
        line = line.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            cur = line[1:-1].strip()
            sections.setdefault(cur, {})
            continue
        if "=" in line and cur is not None:
            k, v = line.split("=", 1)
            sections[cur][k.strip().lower()] = v.strip()
    return sections


# ---------------------------------------------------------------- main
def main(inp, outfile):
    ini = parse_ini(os.path.join(inp, "policy.ini"))
    stmt = ini["statement"]
    library = stmt["library"]
    period_start = parse_date(stmt["period_start"])
    period_end = parse_date(stmt["period_end"])

    clock = ini.get("clock", {})
    base_offset = parse_offset(clock.get("offset", "+00:00"))
    changes = []
    for part in clock.get("changes", "").split(";"):
        part = part.strip()
        if not part:
            continue
        inst, off = part.split()
        t = datetime.strptime(inst, "%Y-%m-%dT%H:%MZ")
        changes.append((t, parse_offset(off)))
    changes.sort()

    def offset_at(utc_naive):
        off = base_offset
        for t, o in changes:
            if t <= utc_naive:
                off = o
            else:
                break
        return off

    items = {}  # lower type -> (name, params)
    cats = {}
    for name, sec in ini.items():
        if name.lower().startswith("item:"):
            tname = name[5:].strip()
            items[tname.lower()] = (tname, {
                "loan_days": int(sec["loan_days"]),
                "renewals": int(sec["renewals"]),
                "grace": int(sec["grace_days"]),
                "daily": cents(sec["daily"]),
                "loan_cap": cents(sec["loan_cap"]),
            })
        elif name.lower().startswith("category:"):
            cname = name[9:].strip()
            sc = sec.get("statement_cap", "none").strip()
            cats[cname.lower()] = (cname, {
                "cap": None if sc.lower() == "none" or sc == "" else cents(sc),
                "discount": int(sec.get("discount", "0") or 0),
                "exempt": {x.strip().lower() for x in sec.get("exempt", "").split(",") if x.strip()},
            })

    branches = []
    open_days = {}
    for r in read_csv(os.path.join(inp, "branches.csv")):
        b = r["branch"].strip()
        branches.append(b)
        open_days[b.upper()] = {w.strip().lower()[:3] for w in r["open_days"].split() if w.strip()}

    cal_rows = []
    for r in read_csv(os.path.join(inp, "calendar.csv")):
        ds = r["date"].strip()
        if ".." in ds:
            a, b = ds.split("..", 1)
            first, last = parse_date(a), parse_date(b)
        else:
            first = last = parse_date(ds)
        cal_rows.append((first, last, r["branch"].strip().upper(), r["status"].strip().lower()))
    open_cache = {}

    def is_open(branch, d):
        key = (branch, d)
        if key in open_cache:
            return open_cache[key]
        res = None
        for first, last, b, st in cal_rows:
            if b == branch and first <= d <= last:
                res = st == "open"
        if res is None:
            for first, last, b, st in cal_rows:
                if b == "*" and first <= d <= last:
                    res = st == "open"
        if res is None:
            res = WEEKDAYS[d.weekday()] in open_days.get(branch, set())
        open_cache[key] = res
        return res

    def next_open(branch, d):
        # moves to the next open day if d is closed
        n = 0
        while not is_open(branch, d) and n < 20000:
            d += timedelta(days=1)
            n += 1
        return d

    # patrons
    patron_rows = {}
    for r in read_csv(os.path.join(inp, "patrons.csv")):
        k = patron_key(r["patron"])
        patron_rows.setdefault(k, []).append((parse_date(r["since"]), r["patron"].strip(), r["category"].strip()))
    for k in patron_rows:
        patron_rows[k].sort(key=lambda x: x[0])

    def patron_at(k, d):
        best = None
        for row in patron_rows.get(k, []):
            if row[0] <= d:
                best = row
        return best

    # waivers
    waivers = {}
    for r in read_csv(os.path.join(inp, "waivers.csv")):
        if r["status"].strip().lower() != "active":
            continue
        k = patron_key(r["patron"])
        v = r["value"].strip()
        val = "full" if v.lower() == "full" else cents(v)
        waivers.setdefault(k, []).append((r["loan"].strip(), val))

    # events
    events = {}
    exdir = os.path.join(inp, "exports")
    for fn in sorted(os.listdir(exdir)):
        path = os.path.join(exdir, fn)
        low = fn.lower()
        if not os.path.isfile(path):
            continue
        if low.endswith(".csv"):
            for r in read_csv(path):
                eid = r.get("event", "").strip()
                if not eid or eid in events:
                    continue
                t = datetime.strptime(r["time"].strip(), "%Y-%m-%d %H:%M")
                events[eid] = (r, t)
        elif low.endswith(".jsonl"):
            for line in read_text(path).splitlines():
                line = line.strip()
                if not line:
                    continue
                o = json.loads(line)
                eid = str(o.get("event", "")).strip()
                if not eid or eid in events:
                    continue
                at = o["at"].strip()
                if at.endswith(("Z", "z")):
                    at = at[:-1] + "+00:00"
                dt = datetime.fromisoformat(at)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
                utc = dt.astimezone(timezone.utc).replace(tzinfo=None)
                t = utc + timedelta(minutes=offset_at(utc))
                r = {k: ("" if v is None else str(v)) for k, v in o.items()}
                events[eid] = (r, t)

    cancelled = set()
    for eid, (r, t) in events.items():
        if r.get("type", "").strip().lower() == "void":
            cancelled.add(r.get("target", "").strip())

    checkouts = {}
    loan_events = {}
    for eid, (r, t) in events.items():
        if eid in cancelled:
            continue
        typ = r.get("type", "").strip().lower()
        lid = r.get("loan", "").strip()
        if typ == "checkout":
            checkouts[lid] = (r, t)
        elif typ in ("renew", "return"):
            loan_events.setdefault(lid, []).append((t, typ, r))

    canon_branch = {b.upper(): b for b in branches}

    loans = []
    for lid, (r, t) in checkouts.items():
        cdate = t.date()
        if cdate > period_end:
            continue
        tname, ip = items[r["item_type"].strip().lower()]
        branch = r["branch"].strip().upper()
        due = next_open(branch, cdate + timedelta(days=ip["loan_days"]))
        renewals = 0
        returned = None
        for et, typ, er in sorted(loan_events.get(lid, []), key=lambda x: x[0]):
            ed = et.date()
            if typ == "renew":
                if ed <= due and renewals < ip["renewals"] and ed <= period_end:
                    renewals += 1
                    due = next_open(branch, ed + timedelta(days=ip["loan_days"]))
            else:
                returned = ed
                if er.get("via", "").strip().lower() == "dropbox":
                    returned = ed - timedelta(days=1)
                break
        if returned is not None and returned < period_start:
            continue
        out_at_end = returned is None or returned > period_end
        end_day = period_end if out_at_end else returned
        overdue = 0
        d = due + timedelta(days=1)
        while d <= end_day:
            if is_open(branch, d):
                overdue += 1
            d += timedelta(days=1)
        if overdue < 1:
            continue
        pk = patron_key(r["patron"])
        prow = patron_at(pk, cdate)
        cat = cats[prow[2].lower()][1]
        charged = overdue if overdue > ip["grace"] else 0
        fee = charged * ip["daily"]
        if tname.lower() in cat["exempt"]:
            fee = 0
        fee = min(fee, ip["loan_cap"])
        assessed = (fee * (100 - cat["discount"]) * 2 + 100) // 200  # half up
        assessed = (fee * (100 - cat["discount"]) + 50) // 100
        loans.append({
            "pk": pk, "loan": lid, "item": r.get("item", "").strip(), "item_type": tname,
            "branch": canon_branch.get(branch, r["branch"].strip()),
            "checkout": cdate, "due": due,
            "returned": None if out_at_end else returned,
            "overdue_days": overdue, "charged_days": charged, "assessed": assessed,
        })

    by_patron = {}
    for l in loans:
        by_patron.setdefault(l["pk"], []).append(l)

    statements = []
    for pk in sorted(by_patron):
        ls = by_patron[pk]
        ws = waivers.get(pk, [])
        for l in ls:
            app = [v for (lid, v) in ws if lid == "*" or lid == l["loan"]]
            if any(v == "full" for v in app):
                waived = l["assessed"]
            else:
                waived = min(sum(app), l["assessed"])
            l["waived"] = waived
            l["net"] = l["assessed"] - waived
            l["capped"] = 0
        prow = patron_at(pk, period_end)
        if prow is None:
            prow = patron_at(pk, max(l["checkout"] for l in ls))
        cname, cat = cats[prow[2].lower()]
        cap = cat["cap"]
        if cap is not None:
            excess = sum(l["net"] for l in ls) - cap
            if excess > 0:
                # latest due first, then loan id sorting last first
                order = sorted(ls, key=lambda l: l["loan"], reverse=True)
                order = sorted(order, key=lambda l: l["due"], reverse=True)
                for l in order:
                    if excess <= 0:
                        break
                    g = min(l["net"], excess)
                    l["capped"] = g
                    excess -= g
        ls.sort(key=lambda l: (l["due"], l["loan"]))
        outloans = []
        for l in ls:
            l["billed"] = l["net"] - l["capped"]
            outloans.append({
                "loan": l["loan"], "item": l["item"], "item_type": l["item_type"], "branch": l["branch"],
                "checkout": l["checkout"].isoformat(), "due": l["due"].isoformat(),
                "returned": l["returned"].isoformat() if l["returned"] else None,
                "overdue_days": l["overdue_days"], "charged_days": l["charged_days"],
                "assessed": l["assessed"], "waived": l["waived"], "capped": l["capped"], "billed": l["billed"],
            })
        st = {"patron": prow[1], "category": cname, "loans": outloans}
        for f in ("assessed", "waived", "capped", "billed"):
            st[f] = sum(x[f] for x in outloans)
        statements.append(st)

    summary = []
    for b in branches:
        row = {"branch": b, "loans": 0, "charged_days": 0, "assessed": 0, "waived": 0, "capped": 0, "billed": 0}
        for s in statements:
            for x in s["loans"]:
                if x["branch"] == b:
                    row["loans"] += 1
                    for f in ("charged_days", "assessed", "waived", "capped", "billed"):
                        row[f] += x[f]
        summary.append(row)

    result = {
        "library": library,
        "period": {"start": period_start.isoformat(), "end": period_end.isoformat()},
        "statements": statements,
        "branches": summary,
    }
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
